const PAGE_NAMES={home:"Home",play:"Game player",browser:"Google",games:"Games",tools:"Tools",ai:"AI",bookmarks:"Bookmarks",history:"History",changelog:"Changelog",feedback:"Feedback",settings:"Settings"};
const KEYBIND_ACTIONS=[["newTab","New tab","Open a new Polaris tab."],["closeTab","Close tab","Close the active tab."],["reopenTab","Reopen closed tab","Restore the most recently closed tab."],["address","Focus address bar","Focus the website/search address bar."],["palette","Command palette","Open quick navigation."],["bookmark","Bookmark current page","Save the current website to bookmarks."],["home","Go to Home","Open Home in the current tab."]];
const DEFAULT_KEYBINDS={newTab:["Ctrl+T"],closeTab:["Ctrl+W"],reopenTab:["Ctrl+Shift+T"],address:["Ctrl+L"],palette:["Ctrl+K"],bookmark:["Ctrl+D"],home:["Alt+Home"]};
function getKeybinds(){try{return {...DEFAULT_KEYBINDS,...JSON.parse(localStorage.getItem("polaris-keybinds")||"{}")}}catch{return {...DEFAULT_KEYBINDS}}}
function normaliseCombo(value){return String(value||"").trim().split("+").map(x=>x.trim()).filter(Boolean).map(x=>{const k=x.toLowerCase();return ({ctrl:"Ctrl",control:"Ctrl",cmd:"Meta",meta:"Meta",alt:"Alt",shift:"Shift",esc:"Escape"}[k]||(x.length===1?x.toUpperCase():x))}).join("+")}
function eventCombo(e){const a=[];if(e.ctrlKey)a.push("Ctrl");if(e.altKey)a.push("Alt");if(e.shiftKey)a.push("Shift");if(e.metaKey)a.push("Meta");if(["Control","Alt","Shift","Meta"].includes(e.key))return "";a.push(e.key===" "?"Space":e.key.length===1?e.key.toUpperCase():e.key);return a.join("+")}
function cyclePolarisTab(direction=1){if(state.tabs.length<2)return;const index=state.tabs.findIndex(t=>t.id===state.activeTabId);activatePolarisTab(state.tabs[(index+direction+state.tabs.length)%state.tabs.length].id)}
function activatePolarisTab(id){const tab=state.tabs.find(t=>t.id===id);if(!tab)return;tab.lastActivatedAt=Date.now();state.activeTabId=id;if(tab.page==="browser"&&tab.url){try{tab.frameObj?.frame?.remove()}catch{}tab.frameObj=null;tab.loaded=false;tab.needsRefresh=true;tab.route="browser?url="+encodeURIComponent(tab.url)+"&tab="+encodeURIComponent(tab.id)}else if(!tab.route){tab.route=(tab.page||"home")+"?tab="+encodeURIComponent(tab.id)}persistTabs();renderBrowserTabs();const route=tab.route;if(location.hash.slice(1)===route)navigate();else location.hash=route}
function exportPolarisSession(){const payload={app:"Polaris",version:1,exportedAt:new Date().toISOString(),tabs:state.tabs.map(({title,url,route,page,pinned,group})=>({title,url,route,page,pinned:Boolean(pinned),group:group||""}))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="polaris-session-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("Session backup downloaded.")}
function importPolarisSession(){const raw=prompt("Paste the contents of a Polaris session JSON backup:");if(!raw)return;try{const data=JSON.parse(raw),rows=Array.isArray(data)?data:data.tabs;if(!Array.isArray(rows)||!rows.length)throw Error("No tabs found.");const restored=rows.slice(0,40).map(item=>{const page=PAGE_NAMES[item.page]?item.page:"home";let url="";if(typeof item.url==="string"&&item.url){const parsed=new URL(item.url);if(!["http:","https:"].includes(parsed.protocol))throw Error("Unsupported address in backup.");url=parsed.href}const id=crypto.randomUUID();return{id,title:String(item.title||(url?hostFromUrl(url):PAGE_NAMES[page])).slice(0,80),url,page:url?"browser":page,route:url?"browser?url="+encodeURIComponent(url):page+"?tab="+id,pinned:Boolean(item.pinned),group:String(item.group||"").slice(0,24),frameObj:null,loaded:false}});state.tabs=restored;state.activeTabId=restored[0].id;persistTabs();renderBrowserTabs();location.hash=restored[0].route;toast("Restored "+restored.length+" tabs.")}catch(error){toast("Could not import session: "+error.message)}}
function closeOtherTabs(keepId){const keep=state.tabs.find(t=>t.id===keepId);if(!keep)return;state.tabs=state.tabs.filter(t=>t.id===keepId||t.pinned);state.activeTabId=keepId;persistTabs();renderBrowserTabs();activatePolarisTab(keepId);toast("Other unpinned tabs closed.")}
function setupKeybinds(){document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="tab"){e.preventDefault();cyclePolarisTab(e.shiftKey?-1:1);return}if((e.ctrlKey||e.metaKey)&&/^[1-9]$/.test(e.key)){e.preventDefault();const n=Number(e.key),tab=n===9?state.tabs[state.tabs.length-1]:state.tabs[n-1];if(tab)activatePolarisTab(tab.id);return}const combo=eventCombo(e);if(!combo)return;const binds=getKeybinds();let action="";for(const [id] of KEYBIND_ACTIONS){if((binds[id]||[]).map(normaliseCombo).includes(combo)){action=id;break}}if(!action)return;const t=e.target,typing=t&&(t.matches("input,textarea,select")||t.isContentEditable);if(typing&&!e.ctrlKey&&!e.metaKey&&!e.altKey)return;e.preventDefault();if(action==="newTab")createBrowserTab();else if(action==="closeTab")closeBrowserTab(state.activeTabId);else if(action==="reopenTab"){const c=state.closedTabs.pop();if(c){if(c.page&&c.page!=="browser")createAppTab(c.page);else createBrowserTab(c.url||"")}else toast("No recently closed tab.")}else if(action==="address")document.querySelector("#global-address")?.focus();else if(action==="palette")openPalette();else if(action==="bookmark")document.querySelector("#web-bookmark")?.click();else if(action==="home")location.hash="home"})}
