function normaliseBrowseInput(value){
 const raw=String(value||"").trim();if(!raw)return "";
 if(/^https?:\/\//i.test(raw))return raw;
 if(/^localhost(?::\d+)?(?:\/|$)/i.test(raw))return "http://"+raw;
 if(/^[a-z0-9.-]+\.[a-z]{2,}(?::\d+)?(?:\/.*)?$/i.test(raw))return "https://"+raw;
 const templates={google:"https://www.google.com/search?q=%s",brave:"https://search.brave.com/search?q=%s",duckduckgo:"https://duckduckgo.com/?q=%s",wikipedia:"https://en.wikipedia.org/w/index.php?search=%s",bing:"https://www.bing.com/search?q=%s",custom:browserSettings.customSearchUrl||""};const template=templates[browserSettings.searchEngine]||templates.google;return template.includes("%s")?template.replace(/%s/g,encodeURIComponent(raw)):templates.google.replace("%s",encodeURIComponent(raw));
}
