function faviconUrlForTab(tab){if(!tab?.url)return "";try{const url=new URL(tab.url);if(!["http:","https:"].includes(url.protocol))return "";return "https://www.google.com/s2/favicons?domain_url="+encodeURIComponent(url.origin)+"&sz=64"}catch{return ""}}
function renderBrowserTabs(){
 const strip=document.querySelector("#browser-tab-strip");if(!strip)return;
 const ordered=[...state.tabs].sort((a,b)=>Number(Boolean(b.pinned))-Number(Boolean(a.pinned)));
 strip.innerHTML=ordered.map(tab=>{const icon=tab.url?'<img class="browser-tab-favicon-image" src="'+esc(faviconUrlForTab(tab))+'" alt="" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="browser-tab-favicon" hidden>'+esc((tab.title||"P").slice(0,1).toUpperCase())+'</span>':'<span class="browser-tab-favicon">'+esc(PAGE_ICONS[tab.page]||"P")+'</span>';return '<button type="button" class="browser-tab '+(tab.id===state.activeTabId?"active ":"")+(tab.pinned?"pinned ":"")+(tab.group?"has-tab-group ":"")+'" data-tab-id="'+esc(tab.id)+'" title="'+esc(tab.title||"Home")+(tab.group?" · "+esc(tab.group):"")+'">'+icon+'<span class="browser-tab-title">'+esc(tab.pinned?"◆ ":"")+esc(tab.title||"Home")+'</span>'+(tab.group?'<span class="browser-tab-group-dot" title="'+esc(tab.group)+'"></span>':"")+'<span class="browser-tab-close" data-close-tab="'+esc(tab.id)+'" aria-label="Close tab">×</span></button>'}).join("");
 strip.querySelectorAll("[data-tab-id]").forEach(button=>{button.draggable=true;button.addEventListener("dragstart",e=>{e.dataTransfer.setData("text/polaris-tab",button.dataset.tabId);e.dataTransfer.effectAllowed="move";button.classList.add("is-dragging")});button.addEventListener("dragend",()=>button.classList.remove("is-dragging"));button.addEventListener("dragover",e=>{e.preventDefault();e.dataTransfer.dropEffect="move"});button.addEventListener("drop",e=>{e.preventDefault();const id=e.dataTransfer.getData("text/polaris-tab"),from=state.tabs.findIndex(t=>t.id===id),to=state.tabs.findIndex(t=>t.id===button.dataset.tabId);if(from<0||to<0||from===to)return;const [moved]=state.tabs.splice(from,1);state.tabs.splice(to,0,moved);persistTabs();renderBrowserTabs()});button.addEventListener("auxclick",e=>{if(e.button===1){e.preventDefault();closeBrowserTab(button.dataset.tabId)}});button.addEventListener("click",e=>{if(e.target.closest("[data-close-tab]"))return;const tab=state.tabs.find(t=>t.id===button.dataset.tabId);if(tab)activatePolarisTab(tab.id)});button.addEventListener("contextmenu",e=>{e.preventDefault();e.stopPropagation();window.dispatchEvent(new CustomEvent("polaris:tab-context",{detail:{id:button.dataset.tabId,x:e.clientX,y:e.clientY}}))})});
 strip.querySelectorAll("[data-close-tab]").forEach(button=>button.addEventListener("click",e=>{e.stopPropagation();closeBrowserTab(button.dataset.closeTab)}));
 strip.querySelector('[data-tab-id="'+CSS.escape(state.activeTabId||"")+'"]')?.scrollIntoView({block:"nearest",inline:"nearest"});
}
function renderBookmarksBar(){const bar=document.querySelector("#bookmarks-bar");if(!bar)return;const saved=readBookmarks();const items=saved.map((bookmark,index)=>'<button type="button" class="bookmark-bar-item" data-bookmark-bar-open="'+index+'" title="'+esc(bookmark.title||bookmark.url)+'"><img src="'+esc(faviconUrlForTab({url:bookmark.url}))+'" alt="" loading="lazy" onerror="this.hidden=true;this.nextElementSibling.hidden=false"><span class="bookmark-bar-fallback" hidden>☆</span><span>'+esc(bookmark.title||hostFromUrl(bookmark.url))+'</span></button>').join("");bar.innerHTML='<div class="bookmark-bar-items">'+(items||'<span class="bookmark-bar-empty">Your bookmarks will appear here. Use ☆ to save a website.</span>')+'</div><button type="button" class="bookmark-bar-manage" id="bookmark-bar-manage" title="Manage bookmarks">Manage</button>';bar.querySelectorAll("[data-bookmark-bar-open]").forEach(button=>button.addEventListener("click",()=>{const bookmark=readBookmarks()[Number(button.dataset.bookmarkBarOpen)];if(bookmark)openBrowserAddress(bookmark.url)}));bar.querySelector("#bookmark-bar-manage")?.addEventListener("click",()=>createAppTab("bookmarks"))}
function createBrowserTab(url=""){const id=crypto.randomUUID(),tab={id,title:url?hostFromUrl(url):"Home",url,route:url?"browser?url="+encodeURIComponent(url)+"&tab="+encodeURIComponent(id):"home?tab="+encodeURIComponent(id),page:url?"browser":"home",frameObj:null,loaded:false,lastActivatedAt:Date.now()};state.tabs.push(tab);state.activeTabId=tab.id;renderBrowserTabs();location.hash=tab.route}
