function closeBrowserTab(id){const index=state.tabs.findIndex(t=>t.id===id);if(index<0)return;if(browserSettings.confirmClose&&state.tabs.length===1&&!confirm("Close the last tab?"))return;const wasActive=state.activeTabId===id;const closed=state.tabs[index];state.closedTabs.push({title:closed.title,url:closed.url,route:closed.route,page:closed.page});if(state.closedTabs.length>10)state.closedTabs.shift();state.tabs.splice(index,1);if(!state.tabs.length){state.tabs=[{id:crypto.randomUUID(),title:"Home",url:"",route:"home",page:"home",frameObj:null,loaded:false}];state.activeTabId=state.tabs[0].id;location.hash="home";renderBrowserTabs();return}if(wasActive){const next=state.tabs[Math.min(index,state.tabs.length-1)];state.activeTabId=next.id;location.hash=next.route||(next.url?"browser?url="+encodeURIComponent(next.url):"home")}else renderBrowserTabs();}
